// Prompt: "Human sees and opens drafts"
// Changes: Draft facts shown in the UI – "updated by agent" and the Slovak draft count. Pure, no DOM.

import type { DraftSummary } from '#/server/projects.server'

/** An agent changed (or created) the draft since the human last viewed it. */
export const updatedByAgent = (d: Pick<DraftSummary, 'lastChangedBy' | 'revision' | 'humanViewedRevision'>) =>
  d.lastChangedBy === 'agent' && d.revision > d.humanViewedRevision

/** "1 návrh", "2 návrhy", "5 návrhov" (Slovak plural). */
export function draftCount(n: number) {
  const word = n === 1 ? 'návrh' : n >= 2 && n <= 4 ? 'návrhy' : 'návrhov'
  return `${n} ${word}`
}
